#include <stdio.h>
#include <string.h>

void escape(char *str) {
    int len = strlen(str);
    char *result = (char *)malloc(len * 2 + 1);
    int j = 0;
    for (int i = 0; i < len; i++) {
        if (str[i] == '\\') {
            result[j++] = '\\';
            result[j++] = '\\';
        } else if (str[i] == '\n') {
            result[j++] = '\\';
            result[j++] = 'n';
        } else {
            result[j++] = str[i];
        }
    }
    result[j] = '\0';
    printf("%s\n", result);
    free(result);
}

void unescape(char *str) {
    int len = strlen(str);
    char *result = (char *)malloc(len + 1);
    int j = 0;
    for (int i = 0; i < len; i++) {
        if (str[i] == '\\') {
            if (i + 1 < len) {
                if (str[i + 1] == '\\') {
                    result[j++] = '\\';
                    i++;
                } else if (str[i + 1] == 'n') {
                    result[j++] = '\n';
                    i++;
                }
            }
        } else {
            result[j++] = str[i];
        }
    }
    result[j] = '\0';
    printf("%s\n", result);
    free(result);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    if (strcmp(argv[1], "escape") == 0) {
        escape(argv[2]);
    } else if (strcmp(argv[1], "unescape") == 0) {
        unescape(argv[2]);
    } else {
        printf("INVALID_MODE\n");
    }
    return 0;
}
